-- Sprint 15 (S15-4, F-63): an admin resets the hosted demo from the governance page.
--
-- Migrations hold no sample data (project rule), so this adds only an empty place for the demo's
-- reload script and the functions that use it. The script is stored by supabase/demo-hosted.sql
-- (generated by npm run demo:hosted) when the demo is loaded. An installation where no demo was
-- loaded, such as a local install or a real deployment, has nothing to reset, and the reset refuses.

CREATE TABLE private.demo_reload (
  id            boolean     PRIMARY KEY DEFAULT true CHECK (id),
  script        text        NOT NULL,
  stored_at     timestamptz NOT NULL DEFAULT now(),
  last_reset_at timestamptz
);
ALTER TABLE private.demo_reload ENABLE ROW LEVEL SECURITY;
-- No policy and no grant: only the owner (these functions, and the SQL Editor) reads or writes it.
REVOKE ALL ON private.demo_reload FROM PUBLIC, anon, authenticated, service_role;

-- Whether a demo is loaded, and when it was last reset. Admins only.
CREATE FUNCTION public.demo_status()
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = '' AS $$
DECLARE r private.demo_reload;
BEGIN
  IF NOT access.is_admin() THEN
    RAISE EXCEPTION 'Only an admin can see the demo''s status' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO r FROM private.demo_reload;
  RETURN jsonb_build_object('loaded', r.id IS NOT NULL, 'stored_at', r.stored_at, 'last_reset_at', r.last_reset_at);
END;
$$;
REVOKE ALL ON FUNCTION public.demo_status() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.demo_status() TO authenticated;

-- Removes every response and knowledge-base entry, including what reviewers added, and loads the
-- demo again, exactly as supabase/demo-hosted-reset.sql does in the SQL Editor. Kept: accounts,
-- roles, settings and limits, real people's usage and the audit log; the demo's own recorded usage
-- is replaced, not added to. Entry numbers start again at KB-0001, so the demo responses cite the
-- right entries. Admins only, confirmed by typing the phrase exactly; audited as demo.reset.
CREATE FUNCTION public.reset_demo(p_confirm text)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE
  v_admin  uuid := auth.uid();
  v_claims text := current_setting('request.jwt.claims', true);
  v_script text;
  v_entries int;
  v_responses int;
BEGIN
  IF NOT access.is_admin() THEN
    RAISE EXCEPTION 'Only an admin can reset the demo' USING ERRCODE = '42501';
  END IF;
  IF p_confirm IS DISTINCT FROM 'reset the demo' THEN
    RAISE EXCEPTION 'Type "reset the demo" to confirm' USING ERRCODE = '22023';
  END IF;
  -- One reset at a time; a second waits for the first and then runs on its result.
  PERFORM pg_advisory_xact_lock(hashtext('rfi_respond.reset_demo'));
  SELECT script INTO v_script FROM private.demo_reload FOR UPDATE;
  IF v_script IS NULL THEN
    RAISE EXCEPTION 'No demo is loaded in this installation, so there is nothing to reset' USING ERRCODE = 'P0002';
  END IF;

  TRUNCATE public.opportunities, public.kb_entries RESTART IDENTITY CASCADE;
  DELETE FROM public.ai_usage WHERE user_id IN (SELECT id FROM auth.users WHERE email LIKE '%@example.invalid');
  -- The reload runs as it does in the SQL Editor: as the owner, with nobody signed in (it signs in
  -- the fictional people itself where the demo needs them). Triggers that treat an admin's writes
  -- differently would otherwise mark the demo's entries as reviewed by whoever pressed the button.
  PERFORM set_config('request.jwt.claims', '', true);
  EXECUTE v_script;
  PERFORM set_config('request.jwt.claims', coalesce(v_claims, ''), true);

  UPDATE private.demo_reload SET last_reset_at = now();
  SELECT count(*) INTO v_entries FROM public.kb_entries;
  SELECT count(*) INTO v_responses FROM public.opportunities;
  INSERT INTO public.audit_log (actor, action, target_id, details)
  VALUES (v_admin, 'demo.reset', NULL, jsonb_build_object('entries', v_entries, 'responses', v_responses));
  RETURN jsonb_build_object('entries', v_entries, 'responses', v_responses);
END;
$$;
REVOKE ALL ON FUNCTION public.reset_demo(text) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.reset_demo(text) TO authenticated;
